const repoRoot = process.cwd();
const evidenceDir = path.join(repoRoot, 'applet-readiness-evidence/official-applet');
const evidencePath = path.join(evidenceDir, 'atelier-projection-contract-gate.json');
const projectionContractCoveredPaths = [
  'Atelier projection contract JSON, codegen, official generated contract, and prototype generated contract remain aligned',
  'TaskGraph evidenceRefResolution contract metadata is generated and consumed before unresolved refs are displayed',
  'Atelier P4 readiness slice documentation and ledger entries remain synchronized with NOT_READY boundaries',
  'official Atelier frontend and browser prototype preserve projection-only forbidden capability boundaries',
  'official Atelier service binding and Host intent transport contract anchors remain guarded',
  'browser prototype bridge/runtime recovery, artifact preview, log, attachment, and read-only projection boundaries remain guarded',
  'Atelier acceptance/completion/prototype documentation keeps evidence claim boundaries and NOT_READY readiness wording',
  'existing Atelier evidence JSON files with coveredPaths/notCovered keep claimBoundary consistency',
];
const projectionContractDoesNotProve = [
  'real Desktop product window UI',
  'real Desktop Host capability producer behavior',
  'real Station projection stream failure matrix',
  'real provider, model, shell, artifact, gate, memory, or Host Storage side effects',
  'real artifact body fetch, Host sandbox renderer, Console Logs runtime stream, or attachment upload runtime',
  'complete Host + Station + applet E2E',
];

let p4ReadinessDocSyncSelfCheck = {
  status: 'NOT_RUN',
  sliceCount: 0,
  trackedSliceIds: [],
  requiredDocuments: [],
  notReadyBoundaryDocuments: [],
  missingAnchors: [],
};

function writeProjectionContractEvidence(status, errorMessage) {
  const proves = status === 'PASS' ? projectionContractCoveredPaths : [];
  fs.mkdirSync(evidenceDir, { recursive: true });
  fs.writeFileSync(
    evidencePath,
    `${JSON.stringify(
      {
        status,
        evidenceClass: 'STATIC_CONTRACT_GATE',
        appletId: 'peers.atelier',
        gate: 'atelier:projection-contract-gate',
        coveredPaths: proves,
        notCovered: projectionContractDoesNotProve,
        claimBoundary: {
          readiness: 'NOT_READY',
          proves,
          doesNotProve: projectionContractDoesNotProve,
        },
        docSyncSelfCheck: p4ReadinessDocSyncSelfCheck,
        command: 'pnpm run atelier:projection-contract-gate',
        error: errorMessage,
        completedAt: new Date().toISOString(),
      },
      null,
      2,
    )}\n`,
  );
}

