      bodyRefShape: { scheme: 'artifact', pathSegments: 2, terminalSegment: 'body' },
      sandboxRefShape: { scheme: 'atelier-sandbox', pathSegments: 2, terminalSegment: 'preview' },
      forbiddenBodyFields: ['markdown', 'content', 'body', 'html', 'diff', 'patch', 'url', 'src', 'iframe'],
