function expectP4ReadinessDocSync(contentsByFile) {
  const requiredDocuments = [
    files.prototypeReadme,
    files.atelierAcceptanceEvidenceReport,
    files.atelierCompletionAudit,
    files.masterGoal,
  ];
  const missingAnchors = [];
  for (const slice of p4ReadinessDocSyncSlices) {
    const checks = [
      [files.prototypeReadme, contentsByFile.prototypeReadme, slice.prototype, `${slice.id} prototype README sync anchor`],
      [files.atelierAcceptanceEvidenceReport, contentsByFile.atelierAcceptanceEvidenceReport, slice.acceptance, `${slice.id} acceptance report sync anchor`],
      [files.atelierCompletionAudit, contentsByFile.atelierCompletionAudit, slice.completion, `${slice.id} completion audit sync anchor`],
      [files.masterGoal, contentsByFile.masterGoal, slice.ledger, `${slice.id} master ledger sync anchor`],
      [files.masterGoal, contentsByFile.masterGoal, slice.semanticAnchor, `${slice.id} master ledger semantic anchor`],
    ];
    for (const [file, haystack, needle, label] of checks) {
      if (!haystack.includes(needle)) {
        missingAnchors.push({ id: slice.id, file, label, needle });
      }
    }
    expectIncludes(files.prototypeReadme, contentsByFile.prototypeReadme, slice.prototype, `${slice.id} prototype README sync anchor`);
    expectIncludes(files.atelierAcceptanceEvidenceReport, contentsByFile.atelierAcceptanceEvidenceReport, slice.acceptance, `${slice.id} acceptance report sync anchor`);
    expectIncludes(files.atelierCompletionAudit, contentsByFile.atelierCompletionAudit, slice.completion, `${slice.id} completion audit sync anchor`);
    expectIncludes(files.masterGoal, contentsByFile.masterGoal, slice.ledger, `${slice.id} master ledger sync anchor`);
    expectIncludes(files.masterGoal, contentsByFile.masterGoal, slice.semanticAnchor, `${slice.id} master ledger semantic anchor`);
  }
  const notReadyBoundaryDocuments = [];
  for (const [key, label] of [
    ['prototypeReadme', files.prototypeReadme],
    ['atelierAcceptanceEvidenceReport', files.atelierAcceptanceEvidenceReport],
    ['atelierCompletionAudit', files.atelierCompletionAudit],
    ['masterGoal', files.masterGoal],
  ]) {
    const hasNotReadyBoundary = contentsByFile[key].includes('NOT_READY');
    const hasE2EBoundary = contentsByFile[key].includes('complete Host + Station + applet E2E');
    if (hasNotReadyBoundary && hasE2EBoundary) {
      notReadyBoundaryDocuments.push(label);
    } else {
      missingAnchors.push({
        id: 'P4-readiness-boundary',
        file: label,
        label: 'P4 readiness docs must preserve NOT_READY and complete E2E non-proof boundaries',
        needle: hasNotReadyBoundary ? 'complete Host + Station + applet E2E' : 'NOT_READY',
      });
    }
    expectIncludes(label, contentsByFile[key], 'NOT_READY', 'P4 readiness docs must preserve NOT_READY boundary');
    expectIncludes(label, contentsByFile[key], 'complete Host + Station + applet E2E', 'P4 readiness docs must preserve complete E2E non-proof boundary');
  }
  return {
    status: missingAnchors.length === 0 ? 'PASS' : 'FAIL',
    sliceCount: p4ReadinessDocSyncSlices.length,
    trackedSliceIds: p4ReadinessDocSyncSlices.map((slice) => slice.id),
    requiredDocuments,
    notReadyBoundaryDocuments,
    missingAnchors,
  };
}

