const artifactRendererSurface = contract.artifactRendererSurface;
if (!artifactRendererSurface || typeof artifactRendererSurface !== 'object') {
  failures.push(`${files.contract}: artifactRendererSurface boundary metadata is required`);
} else {
  if (artifactRendererSurface.readiness !== 'controlled_local_upstream') {
    failures.push(`${files.contract}: artifactRendererSurface.readiness must remain controlled_local_upstream until live Desktop webview rendering is proven`);
  }
  if (artifactRendererSurface.owner !== 'desktop_host') {
    failures.push(`${files.contract}: artifactRendererSurface.owner must be desktop_host`);
  }
  if (artifactRendererSurface.source !== 'desktop_host_adapter_unit_matrix') {
    failures.push(`${files.contract}: artifactRendererSurface.source must be desktop_host_adapter_unit_matrix`);
  }
  if (artifactRendererSurface.evidenceClass !== 'CONTROLLED_LOCAL_UPSTREAM') {
    failures.push(`${files.contract}: artifactRendererSurface.evidenceClass must be CONTROLLED_LOCAL_UPSTREAM`);
  }
  if (artifactRendererSurface.surfaceKind !== 'host_sandbox_visual_surface') {
    failures.push(`${files.contract}: artifactRendererSurface.surfaceKind must be host_sandbox_visual_surface`);
  }
  expectExactStringSet(artifactRendererSurface.rendererKinds, ['markdown', 'web', 'image', 'diff'], 'artifactRendererSurface.rendererKinds');
  if (artifactRendererSurface.rendererOwner !== 'desktop_host') {
    failures.push(`${files.contract}: artifactRendererSurface.rendererOwner must be desktop_host`);
  }
  if (artifactRendererSurface.rendererMode !== 'host_sandbox_manifest') {
    failures.push(`${files.contract}: artifactRendererSurface.rendererMode must be host_sandbox_manifest`);
  }
  if (artifactRendererSurface.requiredRendererCapabilitiesFrom !== 'methodPayloads.atelier.artifact.preview.open.requiredRendererCapabilities') {
    failures.push(`${files.contract}: artifactRendererSurface.requiredRendererCapabilitiesFrom must point at preview open requiredRendererCapabilities`);
  }
  if (JSON.stringify(artifactRendererSurface.sandboxPolicy) !== JSON.stringify({
    allowScripts: false,
    allowNetwork: false,
    allowExternalNavigation: false,
    allowFileAccess: false,
    allowPatchApply: false,
  })) {
    failures.push(`${files.contract}: artifactRendererSurface.sandboxPolicy must keep scripts/network/navigation/file/patch disabled`);
  }
  if (artifactRendererSurface.rawBodyExposedToApplet !== false) {
    failures.push(`${files.contract}: artifactRendererSurface.rawBodyExposedToApplet must be false`);
  }
  if (artifactRendererSurface.appletRenderable !== false) {
    failures.push(`${files.contract}: artifactRendererSurface.appletRenderable must be false`);
  }
  expectExactStringSet(artifactRendererSurface.forbiddenFields, ['url', 'src', 'href', 'iframe', 'html', 'image', 'file', 'path', 'execute', 'run', 'openExternalUrl'], 'artifactRendererSurface.forbiddenFields');
  if (artifactRendererSurface.controlledEvidence?.readiness !== 'controlled_local_upstream') {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.readiness must be controlled_local_upstream`);
  }
  if (artifactRendererSurface.controlledEvidence?.evidenceClass !== 'CONTROLLED_LOCAL_UPSTREAM') {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.evidenceClass must be CONTROLLED_LOCAL_UPSTREAM`);
  }
  if (artifactRendererSurface.controlledEvidence?.gate !== 'atelier:artifact-renderer-controlled-gate') {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.gate must be atelier:artifact-renderer-controlled-gate`);
  }
  expectExactStringSet(
    artifactRendererSurface.controlledEvidence?.evidenceFiles ?? [],
    ['applet-readiness-evidence/official-applet/atelier-artifact-renderer-controlled-gate.json'],
    'artifactRendererSurface.controlledEvidence.evidenceFiles',
  );
  if (artifactRendererSurface.controlledEvidence?.source !== artifactRendererSurface.source) {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.source must match artifactRendererSurface.source`);
  }
  if (artifactRendererSurface.controlledEvidence?.surfaceKind !== artifactRendererSurface.surfaceKind) {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.surfaceKind must match artifactRendererSurface.surfaceKind`);
  }
  expectExactStringSet(
    artifactRendererSurface.controlledEvidence?.rendererKinds ?? [],
    artifactRendererSurface.rendererKinds ?? [],
    'artifactRendererSurface.controlledEvidence.rendererKinds',
  );
  expectExactStringSet(
    artifactRendererSurface.controlledEvidence?.runtimeEvidenceBlocks ?? [],
    ['markdownRuntimeEvidence', 'diffRuntimeEvidence', 'webRuntimeEvidence', 'imageRuntimeEvidence'],
    'artifactRendererSurface.controlledEvidence.runtimeEvidenceBlocks',
  );
  expectExactStringSet(
    artifactRendererSurface.controlledEvidence?.rawExposureFlags ?? [],
    ['rawBodyExposedToApplet', 'rawDiffExposedToApplet', 'rawHtmlExposedToApplet', 'rawImageBytesExposedToApplet'],
    'artifactRendererSurface.controlledEvidence.rawExposureFlags',
  );
  if (artifactRendererSurface.controlledEvidence?.appletRenderable !== false) {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.appletRenderable must be false`);
  }
  if (artifactRendererSurface.controlledEvidence?.liveWebviewProven !== false) {
    failures.push(`${files.contract}: artifactRendererSurface.controlledEvidence.liveWebviewProven must be false`);
  }
  for (const gap of ['real iframe/image/html/diff rendering in a live Desktop webview', 'real artifact blob fetch from Station storage', 'complete Host + Station + applet E2E']) {
    if (!artifactRendererSurface.claimBoundary?.doesNotProve?.includes(gap)) {
      failures.push(`${files.contract}: artifactRendererSurface.claimBoundary.doesNotProve must include ${gap}`);
    }
  }
}
